data = {
"Delta": (58048, 61643, 5995),
"United": (53717, 57063, 5096),
"Southwest": (26091, 27483, 321),
"American": (52788, 54211, 2614),
"Alaska": (10426, 11735, 570),
}
growth = {k: (v[1]-v[0])/v[0]*100 for k,v in data.items()}
margin = {k: v[2]/v[1]*100 for k,v in data.items()}
print("Revenue growth %:")
for k,v in sorted(growth.items(), key=lambda x:-x[1]):
    print(k, round(v,2))
print("\nOperating margin %:")
for k,v in sorted(margin.items(), key=lambda x:-x[1]):
    print(k, round(v,2))

